{
  "hypotheses": [
    {
      "text": "Duplicate revenue facts for the same company, concept, and period cause primary‑key violations in the revenue_fact table.",
      "how_to_test": "SELECT cik, concept, period_start, period_end, fiscal_year, fiscal_period, COUNT(*) AS dup_cnt\nFROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact\nGROUP BY cik, concept, period_start, period_end, fiscal_year, fiscal_period\nHAVING COUNT(*) > 1;"
    },
    {
      "text": "Some revenue_fact rows reference a CIK that does not exist in the company table, breaking the foreign‑key rule revenue_fact.cik → company.cik.",
      "how_to_test": "SELECT rf.cik\nFROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact rf\nLEFT JOIN lightning.metastore.explainwhy.explainwhy_usl.company cp ON rf.cik::int = cp.cik\nWHERE cp.cik IS NULL;"
    },
    {
      "text": "Company profiles contain SIC codes that are missing from the sic_codes_table reference, violating the foreign‑key rule company.sic_code → sic_codes_table.sic_code.",
      "how_to_test": "SELECT cp.cik, cp.sic_code\nFROM lightning.metastore.explainwhy.explainwhy_usl.company cp\nLEFT JOIN company_dns.sic_codes_table s ON cp.sic_code = s.sic_code\nWHERE s.sic_code IS NULL;"
    },
    {
      "text": "Tagging errors where the concept 'RevenueFromContractWithCustomerExcludingAssessedTax' is used for periods that should only have 'Revenues', creating impossible value ranges (e.g., negative revenues) that trigger a business‑rule check implemented as a DQ rule.",
      "how_to_test": "SELECT rf.cik, rf.concept, rf.value_usd\nFROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact rf\nWHERE rf.concept = 'RevenueFromContractWithCustomerExcludingAssessedTax'\n  AND rf.value_usd < 0;"
    }
  ]
}
